import{f as o,o as t,c as d,a6 as r}from"./chunks/framework.Dd1qhYRL.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),a={name:"guide/troubleshooting.md"};function n(c,e,s,i,h,l){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>Find the message you see, read the cause, and apply the fix. Exit code <code>2</code> means the command never ran, <code>1</code> means it failed and a retry is safe, and <code>3</code> means some work landed (<a href="/headless.html#exit-codes">exit codes</a>).</p><h2 id="why-does-a-command-fail-or-surprise-me" tabindex="-1">Why does a command fail or surprise me? <a class="header-anchor" href="#why-does-a-command-fail-or-surprise-me" aria-label="Permalink to “Why does a command fail or surprise me?”">​</a></h2><table tabindex="0"><thead><tr><th>Message or symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Unrecognized flag &#39;--config&#39; before the subcommand</code></td><td>Only <code>-c</code>/<code>--cwd</code> is a root flag</td><td><code>noorm run build --config prod</code></td></tr><tr><td><code>Error: --cwd path is not a directory: …/prod</code></td><td>In <code>noorm -c prod run build</code>, <code>-c</code> means <code>--cwd</code></td><td><code>noorm run build -c prod</code></td></tr><tr><td><code>Unknown command help</code></td><td>There is no <code>noorm help</code></td><td><code>noorm db create --help</code></td></tr><tr><td><code>db create --name foo</code> creates nothing named <code>foo</code></td><td><code>db create</code> has no <code>--name</code>. The config names the database</td><td><code>noorm config import dev-config.json</code>, then <code>noorm db create -c dev</code></td></tr><tr><td><code>Unknown command</code> from <code>noorm sql &quot;…&quot;</code></td><td>The <code>sql query</code> rewrite needs the query to start with a SQL verb, so a leading comment defeats it</td><td><code>noorm sql query &quot;…&quot;</code></td></tr><tr><td><code>Error: noorm init requires an interactive terminal.</code></td><td>No terminal, no <code>--yes</code></td><td><code>noorm identity init …</code>, then <code>noorm init --yes</code></td></tr><tr><td><code>--dry-run</code> leaves files in <code>tmp/</code></td><td>It renders SQL there with secrets resolved, and <code>tmp/</code> is not gitignored</td><td>Delete <code>tmp/</code>, or use <code>noorm run preview &lt;path&gt;</code></td></tr></tbody></table><h2 id="why-does-the-database-refuse-or-misbehave" tabindex="-1">Why does the database refuse or misbehave? <a class="header-anchor" href="#why-does-the-database-refuse-or-misbehave" aria-label="Permalink to “Why does the database refuse or misbehave?”">​</a></h2><p>Each server sends one error for a wrong password and an unknown account. noorm rewords it, and the server&#39;s own text is in <code>.noorm/state/noorm.log</code> (<code>connection:error</code>, fields <code>serverCode</code> and <code>serverMessage</code>).</p><table tabindex="0"><thead><tr><th>Message</th><th>Also sent for</th></tr></thead><tbody><tr><td><code>Login failed for user …</code> (SQL Server)</td><td>Unknown login, login denied <code>CONNECT SQL</code>, Windows-only authentication</td></tr><tr><td><code>Password authentication failed for user …</code> (PostgreSQL)</td><td>Unknown role, password past <code>VALID UNTIL</code></td></tr><tr><td><code>Access denied for user …</code> (MySQL)</td><td>Unknown user, no account for this client host, <code>REQUIRE SSL</code> account</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>A right password fails from <code>NOORM_CONNECTION_PASSWORD</code></td><td>The compiled binary does not read <code>.env</code> files</td><td>Export the variable, or set it in CI</td></tr><tr><td>An MSSQL procedure&#39;s <code>DEFAULT</code> is not applied</td><td>The SDK sends <code>undefined</code> as <code>NULL</code>, and MSSQL applies a <code>DEFAULT</code> only to an omitted parameter</td><td><code>.default(value)</code> in the Zod schema, or omit the key (<a href="/reference/sdk.html#parameter-handling-and-null-semantics">details</a>)</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/cli/flags.html">CLI flag conventions</a>: where each flag goes</li><li><a href="/guide/automation/non-interactive.html">Non-interactive operation</a>: <code>--yes</code> and what still refuses</li></ul>',10)])])}const f=o(a,[["render",n]]);export{u as __pageData,f as default};
